# ============================================================
#  wolfXsms Centered Popup Toast
#  Run inside wolfXsms folder: .\setup-toasts-v2.ps1
# ============================================================

Write-Host ""
Write-Host "  Installing centered popup toast..." -ForegroundColor Yellow
Write-Host ""

New-Item -ItemType Directory -Force -Path "$PSScriptRoot\src\context" | Out-Null

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes("$PSScriptRoot\src\context\ToastContext.tsx", $bytes)
Write-Host "  [OK] ToastContext.tsx" -ForegroundColor Green

Write-Host ""
Write-Host "  Done! Run: npm run dev" -ForegroundColor Cyan
Write-Host ""